import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
        Scanner sc = new Scanner(System.in);
        StringBuilder sb = new StringBuilder();
        int tc = sc.nextInt();
        while(tc -- > 0) {
            int n = sc.nextInt();
            int m = 3*n;
            int[] a = new int[m];
            
            for(int i=0;i<m;i++){
                a[i] = sc.nextInt();
            }
            
            Arrays.sort(a);
            
            for(int i=0;i<m/2;i++) {
                int z = a[i];
                a[i] = a[m-1-i];
                a[m - 1 - i] = z;
            }
            
            long[] p = new long[m+1];
            for(int i=0;i<m;i++) {
                p[i + 1] = p[i] + a[i]; 
            }
            
            long ans = 0;
            int y = 0;
            
            for(int x=n;x>=0;x--) {
                while(y<n-x) {
                    int i=x+2*y;
                    int j=m-2*x-y-1;
                    if((long) a[i] + a[i + 1] <= 3L * a[j]) {
                        break;
                    }
                    y++;
                }
                
                long v = 2L * p[x] + p[x+2*y] + 3L * p[m-2*x-y];
                ans = Math.max(ans, v);
            }
            sb.append(ans).append("\n");
        }
        System.out.println(sb);
	}
}
